package cn.codedog.ranking;
import cn.codedog.service.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.time.*;import java.sql.Timestamp;import java.util.*;import static org.assertj.core.api.Assertions.*;
class RankingMonthlyServiceTest {
 JdbcTemplate j;RankingMonthlyService service;
 @BeforeEach void setup(){j=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:mem:monthly-"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","sa",""));cn.codedog.OperationsTestSchema.create(j);
 j.execute("CREATE TABLE users(username VARCHAR(50) PRIMARY KEY)");j.update("INSERT INTO users VALUES('a'),('b')");
 j.execute("CREATE TABLE ranking_students(owner_username VARCHAR(50),camp_id VARCHAR(100),class_id VARCHAR(100),student_id VARCHAR(100),student_name VARCHAR(100))");
 j.execute("CREATE TABLE ranking_lessons(owner_username VARCHAR(50),camp_id VARCHAR(100),class_id VARCHAR(100),lesson_id VARCHAR(100),lesson_name VARCHAR(200),ended_at TIMESTAMP(6),updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP)");
 j.execute("CREATE TABLE ranking_lesson_results(owner_username VARCHAR(50),camp_id VARCHAR(100),class_id VARCHAR(100),lesson_id VARCHAR(100),student_id VARCHAR(100),total_points INT,updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP)");
 service=new RankingMonthlyService(j);for(String id:List.of("1","2","3"))j.update("INSERT INTO ranking_students VALUES('a','c','k',?,?)",id,"学生"+id);
 lesson("l1","2026-09-30T16:00:00Z");lesson("l2","2026-10-31T16:00:00Z");lesson("missing",null);
 result("1","l1",2);result("1","l2",9);result("1","missing",7);result("2","l1",2);result("3","l1",1);}
 void lesson(String id,String time){j.update("INSERT INTO ranking_lessons(owner_username,camp_id,class_id,lesson_id,lesson_name,ended_at) VALUES('a','c','k',?,?,?)",id,id,time==null?null:Timestamp.from(Instant.parse(time)));}
 void result(String student,String lesson,int score){j.update("INSERT INTO ranking_lesson_results(owner_username,camp_id,class_id,lesson_id,student_id,total_points) VALUES('a','c','k',?,?,?)",lesson,student,score);}
 @Test void naturalMonthUsesShanghaiBoundariesAndCompetitionRanks(){var board=service.board("a","2026-10",null);var rows=(List<Map<String,Object>>)board.get("rankings");assertThat(rows).extracting(r->((Number)r.get("earned_points")).intValue()).containsExactly(2,2,1);assertThat(rows).extracting(r->r.get("rank")).containsExactly(1,1,3);assertThat(board.get("missingDateCount")).isEqualTo(1L);assertThat((List<?>)service.board("b","2026-10",null).get("rankings")).isEmpty();}
 @Test void correctingActualDateRecalculatesHistoricalMonthWithoutGuessing(){service.date("a",new RankingMonthlyService.LessonDate("c","k","missing",Instant.parse("2026-10-01T08:00:00Z")));var board=service.board("a","2026-10",null);assertThat(((Number)((List<Map<String,Object>>)board.get("rankings")).getFirst().get("earned_points")).intValue()).isEqualTo(9);assertThat(board.get("missingDateCount")).isEqualTo(0L);assertThatThrownBy(()->service.date("b",new RankingMonthlyService.LessonDate("c","k","l1",Instant.parse("2026-10-01T08:00:00Z")))).hasMessageContaining("不属于当前老师");assertThatThrownBy(()->service.board("a","invalid",null)).hasMessageContaining("月份格式");}
 @Test void messagesAreIsolatedPaginatedAndReadIdempotently(){var n=new RankingMessageService(j);n.student("a","1","same","积分变动","+1","ledger");n.student("a","1","same","积分变动","+1","ledger");n.student("a","2","same","其他人","+2","ledger");var box=n.list("a","STUDENT","1",0);assertThat(box.get("total")).isEqualTo(1L);assertThat(box.get("unread")).isEqualTo(1L);long id=((Number)((List<Map<String,Object>>)box.get("items")).getFirst().get("id")).longValue();assertThatThrownBy(()->n.read("a","STUDENT","2",id)).hasMessageContaining("消息不存在");n.read("a","STUDENT","1",id);n.read("a","STUDENT","1",id);assertThat(n.list("a","STUDENT","1",0).get("unread")).isEqualTo(0L);assertThat((List<?>)n.list("a","STUDENT","1",1).get("items")).isEmpty();}
 @Test void studentMonthlyShowsOnlyFirstTenAndOwnRowEvenWithManyTies(){for(int n=0;n<20;n++)j.update("INSERT INTO ranking_students VALUES('a','c','k',?,?)","z"+n,"其他学生"+n);var rows=(List<Map<String,Object>>)service.board("a","2026-10","z19").get("rankings");assertThat(rows).hasSize(11);assertThat(rows).anyMatch(r->r.get("student_id").equals("z19"));}

}
